import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem109 preserva identidade, links e preço',()=>{for(const [n,titulo,expected,link] of [["6208948636","Tênis Converse Feminino Taylor Ct2834 Curto T","Tênis Converse CT2834 feminino — rosa, segundo o anúncio","https://www.mercadolivre.com.br/up/MLBU3401733117?pdp_filters=item_id%3AMLB6208948644"],["6619764606","Webcam 1080p 2mp Full Hd Alta Resolução Com Microfone Usb","Webcam USB com microfone — 1080p anunciados","https://www.mercadolivre.com.br/up/MLBU3907288120?pdp_filters=item_id%3AMLB6619764606"],["6655583300","Lavadora Alta Pressão Portátil Chiaperini Lj14l Cor Azul E Preto","Lavadora Chiaperini LJ14L — vazão anunciada de até 14 L/min","https://www.mercadolivre.com.br/p/MLB55754694?wid=MLB6655583300"]]){const p={id:'mlMLB'+n,titulo,link,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).comentario,p.comentario);}});
